(() => {
 const M=IRRBB_MATH,esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),m=IRRBB_UI.m;
 window.IRRBB_BOOK=M.preset('retail');let selectedRow=0,last;
 const types=[['fixed','Fixed bullet / bond'],['mortgage','Amortising mortgage'],['float','Floating-rate loan / funding'],['term','Term deposit with withdrawal'],['nmd','Non-maturity deposits'],['swap','Fixed / floating swap']];
 const fields={amount:['Balance / notional (£m equivalent)',0,1000,1],rate:['Current annual coupon (%)',-2,20,.25],maturity:['Maturity / core repricing (years)',.25,30,.25],reset:['Next reset / deposit lag (months)',1,60,1],margin:['Commercial margin (%)',-5,5,.25],cpr:['Annual CPR (%)',0,80,1],core:['Core deposit share (%)',0,90,5],beta:['Deposit pass-through (%)',0,100,5]};
 const options=(arr,value)=>arr.map(([v,label])=>`<option value="${v}" ${value===v?'selected':''}>${esc(label)}</option>`).join('');
 function editor(){const target=document.getElementById('balance-builder');
  target.innerHTML=`<div class="lab-steps"><span><b>1</b> Build cash flows</span><span><b>2</b> Apply supervisory shocks</span><span><b>3</b> Explain ΔEVE / ΔNII</span></div><div class="builder-head"><div><span class="mini">YOUR BANKING BOOK</span><h2>Design the balance sheet</h2><p>Start with a preset, then edit or add positions. All balances use one selected shock currency.</p></div><div class="builder-actions"><label for="book-preset">Example portfolio</label><select id="book-preset"><option value="retail">Retail bank</option><option value="matched">Exactly matched fixed book</option><option value="floating">Floating loans / sticky deposits</option></select><button id="load-preset">Load example</button></div></div><div id="book-preview" class="book-preview" aria-live="polite"></div><div id="book-rows">${IRRBB_BOOK.map((row,i)=>{
   const relevant=['amount','rate','maturity',...(row.type==='float'||row.type==='swap'||row.type==='nmd'?['reset']:[]),...(row.type==='mortgage'||row.type==='term'?['cpr']:[]),...(row.type==='nmd'?['core','beta']:[]),...(row.type==='swap'?[]:['margin'])];
   return `<article class="book-row"><div class="row-title"><label>Position name<input data-row="${i}" data-key="name" value="${esc(row.name)}" maxlength="70"></label><button data-remove="${i}" aria-label="Remove ${esc(row.name)}">Remove</button></div><div class="row-fields"><label>Product<select data-row="${i}" data-key="type">${options(types,row.type)}</select></label><label>Direction<select data-row="${i}" data-key="side">${options(row.type==='swap'?[['asset','Receive fixed / pay floating'],['liability','Pay fixed / receive floating']]:[['asset','Asset · receive payments'],['liability','Liability · pay payments']],row.side)}</select></label>${relevant.map(key=>{const [label,min,max,step]=fields[key];return `<label>${esc(key==='cpr'&&row.type==='term'?'One-time early withdrawal (%)':key==='rate'&&row.type==='swap'?'Fixed swap coupon (%)':label)}<input type="number" data-row="${i}" data-key="${key}" value="${Number((key==='reset'?row[key]*12:row[key]).toFixed(6))}" min="${min}" max="${row.type==='nmd'&&key==='maturity'?5:max}" step="any" inputmode="decimal"></label>`}).join('')}</div>${row.type==='nmd'?'<p class="row-note">Core maturity is a synthetic average (max 5y here); non-core principal is overnight for EVE. Beta and lag govern NII separately. NMD balance is maintained in both NII modes.</p>':row.type==='swap'?'<p class="row-note">Simplified fixed / floating repricing legs. Asset direction receives fixed; liability direction pays fixed. No actual notional exchange is assumed.</p>':row.type==='float'?'<p class="row-note">For EVE, principal is slotted at first reset as a repricing proxy. The contractual balance remains until maturity for NII.</p>':''}</article>`;
  }).join('')}</div><div class="builder-bottom"><button id="add-position">+ Add position</button><span id="book-status" role="status" aria-live="polite">${IRRBB_BOOK.length} positions · edits update the results below</span><a href="#cashflows">Learn how schedules are built →</a></div>`;
  target.querySelectorAll('[data-key]').forEach(el=>el.onchange=()=>{
   const i=+el.dataset.row,key=el.dataset.key,row=IRRBB_BOOK[i];let v=el.value;
   if(fields[key]){v=Number(v);const [,min,max]=fields[key];if(el.value.trim()===''||!Number.isFinite(v)||v<min||v>max||key==='maturity'&&row.type==='nmd'&&v>5){el.setAttribute('aria-invalid','true');document.getElementById('book-status').textContent=`Enter ${min}–${row.type==='nmd'&&key==='maturity'?5:max} for ${fields[key][0]}. The last valid calculation is retained.`;return;}if(key==='maturity')v=Math.max(.25,Math.round(v*12)/12);if(key==='reset')v=Math.round(v)/12;el.value=String(key==='reset'?v*12:v);}
   if(key==='name')v=v.trim()||'Position '+(i+1);row[key]=v;el.removeAttribute('aria-invalid');
   if(key==='type'){if(['term','nmd'].includes(v))row.side='liability';if(v==='nmd')row.maturity=Math.min(5,row.maturity);editor();}
   if(key==='maturity'&&row.type!=='nmd'){row.reset=Math.min(row.reset,row.maturity);const reset=target.querySelector('[data-row="'+i+'"][data-key="reset"]');if(reset)reset.value=row.reset*12;}
   document.getElementById('book-status').textContent='Updated. Results use the latest valid inputs.';window.IRRBB_APP.refresh();
  });
  target.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{IRRBB_BOOK.splice(+el.dataset.remove,1);selectedRow=0;editor();IRRBB_APP.refresh();});
  document.getElementById('add-position').onclick=()=>{if(IRRBB_BOOK.length>=12){document.getElementById('book-status').textContent='This learning lab supports up to 12 positions.';return;}IRRBB_BOOK.push(M.row('New fixed loan','fixed','asset',25,4,5));editor();IRRBB_APP.refresh();};
  document.getElementById('load-preset').onclick=()=>{const name=document.getElementById('book-preset').value;window.IRRBB_BOOK=M.preset(name);selectedRow=0;editor();document.getElementById('book-preset').value=name;IRRBB_APP.refresh();};
 }
 window.renderIRRBBBuilder=id=>{const el=document.getElementById('balance-builder');el.hidden=id!=='lab';if(id==='lab')editor();};
 const table=(headers,rows)=>`<table><thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 const csv=x=>{let s=String(x);if(typeof x==='string'&&/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
 function download(name,rows){const blob=new Blob([rows.map(row=>row.map(csv).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 window.renderIRRBBDetail=r=>{const el=document.getElementById('lab-detail');el.hidden=!r;if(!r)return;last=r;selectedRow=Math.min(selectedRow,Math.max(0,r.book.length-1));
  const preview=document.getElementById('book-preview');if(preview)preview.innerHTML=`<span><small>${esc(r.selected.label)} · ΔEVE</small><strong>${m(r.selected.deve)}</strong></span><span><small>${r.options.horizon}-year ΔNII</small><strong>${m(r.selected.dnii)}</strong></span><span><small>Worst EVE decline / Tier 1</small><strong>${IRRBB_UI.p(r.ratio)}</strong></span><button id="jump-results">Inspect the results ↓</button>`;if(preview)document.getElementById('jump-results').onclick=()=>document.querySelector('.workspace').scrollIntoView({behavior:'smooth'});
  const o=r.options,id=o.scenario,asset=M.sum(r.book.filter(x=>x.side==='asset'&&x.type!=='swap').map(x=>x.amount)),liability=M.sum(r.book.filter(x=>x.side==='liability'&&x.type!=='swap').map(x=>x.amount));
  el.innerHTML=`<div class="lab-audit"><span class="mini">TRACE THE RESULT</span><h2>From positions to value and income</h2><p>Asset balances ${m(asset)}; funding balances ${m(liability)}; residual book funding/equity ${m(asset-liability)}. Tier 1 is an independent input. Swap notional is excluded from these balances.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Position contributions">${table(['Position','Base PV','Shocked PV','ΔEVE contribution','Base NII','Shocked NII'],r.book.map(row=>{const b=M.value(row,o),v=M.value(row,o,id);return[row.name,m(b),m(v),m(v-b),m(M.sum(M.nii(row,o).map(x=>x.value))),m(M.sum(M.nii(row,o,id).map(x=>x.value)))];}))}</div><div class="detail-tools"><label>Inspect a position<select id="inspect-row">${r.book.map((row,i)=>`<option value="${i}" ${i===selectedRow?'selected':''}>${esc(row.name)}</option>`).join('')}</select></label><button id="export-flows">Download all cash flows CSV</button><button id="export-results">Download scenario results CSV</button></div><p class="row-note">The table below shows the first 24 repricing cash flows of the selected position. Download includes all positions and dates. Floating and swap repricing principal is a valuation proxy, not an actual repayment schedule.</p><div id="flow-detail" class="table-scroll" tabindex="0" role="region" aria-label="Cash-flow valuation trace"></div></div>`;
  const flowTable=()=>{const row=r.book[selectedRow];document.getElementById('flow-detail').innerHTML=table(['Time (y)','Type','Signed principal','Signed interest','Total CF','Discount factor','PV'],row?M.flows(row,o,id).slice(0,24).map(x=>[x.t.toFixed(3),x.kind,m(x.principal),m(x.interest),m(x.cf),M.df(x.t,o,id,x.spread).toFixed(6),m(x.cf*M.df(x.t,o,id,x.spread))]):[]);};flowTable();
  document.getElementById('inspect-row').onchange=e=>{selectedRow=+e.target.value;flowTable();};
  document.getElementById('export-flows').onclick=()=>download('irrbb-cashflows.csv',[['position','type','side','currency','scenario','time_years','principal_m','interest_m','total_cf_m','discount_factor','pv_m','margins','floor','base_short_pct','base_long_pct'],...r.book.flatMap(row=>['base',id].flatMap(s=>M.flows(row,o,s).map(x=>[row.name,row.type,row.side,o.currency,s,x.t,x.principal,x.interest,x.cf,M.df(x.t,o,s,x.spread),x.cf*M.df(x.t,o,s,x.spread),o.margins,o.floor,o.short,o.long])))]);
  document.getElementById('export-results').onclick=()=>download('irrbb-scenarios.csv',[['scenario','currency','baseline_eve_m','shocked_eve_m','delta_eve_m','baseline_nii_m','shocked_nii_m','delta_nii_m','horizon_years','nii_balance','tier1_m','floor','margins','short_pct','long_pct'],...r.scenarios.map(x=>[x.label,o.currency,r.baseEve,x.eve,x.deve,r.baseNii,x.nii,x.dnii,o.horizon,o.balance,o.tier1,o.floor,o.margins,o.short,o.long])]);
 };
})();
